SELECT dataset_id,release_id,contract_version,date,market,code,instrument_class,hex(reinterpretAsFixedString(open)) AS open_bits,hex(reinterpretAsFixedString(high)) AS high_bits,hex(reinterpretAsFixedString(low)) AS low_bits,hex(reinterpretAsFixedString(close)) AS close_bits,hex(reinterpretAsFixedString(amount_cny)) AS amount_cny_bits,hex(reinterpretAsFixedString(volume_shares)) AS volume_shares_bits FROM rustdx_recovery_c460890aa1f94602bc3495fcbd7c77e2.bars ORDER BY dataset_id,release_id,contract_version,date,market,code,instrument_class FORMAT JSONEachRow
